import type { ImgHTMLAttributes } from "react";
import { getLargestUrl, getSrcSet } from "../../lib/imageManifest";

type Role = "hero" | "grid" | "gallery";

const DEFAULT_SIZES: Record<Role, string> = {
  hero: "100vw",
  grid: "(max-width: 640px) 100vw, (max-width: 1024px) 50vw, 33vw",
  gallery: "(max-width: 768px) 100vw, 60vw",
};

interface ResponsiveImageProps extends Omit<ImgHTMLAttributes<HTMLImageElement>, "src" | "srcSet"> {
  /** Basename of the image as generated by scripts/optimize-images.mjs (no extension/size suffix). */
  name: string;
  alt: string;
  role?: Role;
  sizes?: string;
}

/**
 * Renders a `<picture>` with WebP + JPG responsive sources, sourced from the
 * manifest of pre-generated derivatives (scripts/optimize-images.mjs).
 */
export default function ResponsiveImage({
  name,
  alt,
  role = "grid",
  sizes,
  loading = "lazy",
  decoding = "async",
  ...rest
}: ResponsiveImageProps) {
  const webpSrcSet = getSrcSet(name, "webp");
  const jpgSrcSet = getSrcSet(name, "jpg");
  const fallbackSrc = getLargestUrl(name, "jpg") || getLargestUrl(name, "webp");
  const sizesAttr = sizes ?? DEFAULT_SIZES[role];

  return (
    <picture>
      {webpSrcSet && <source type="image/webp" srcSet={webpSrcSet} sizes={sizesAttr} />}
      {jpgSrcSet && <source type="image/jpeg" srcSet={jpgSrcSet} sizes={sizesAttr} />}
      <img
        src={fallbackSrc}
        alt={alt}
        loading={loading}
        decoding={decoding}
        {...rest}
      />
    </picture>
  );
}
